import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ShiftTrackingDtlJobOptionsDto } from './dtos/shift-tracking-dtl-job-options.dto';
import { ShiftTrackingDtl } from './shift-tracking-details.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ShiftTrackingDtlCleanupService {
  private readonly logger = new AppLogger(ShiftTrackingDtlCleanupService.name);

  public constructor(
    @InjectRepository(ShiftTrackingDtl)
    private readonly shiftTrackingDtlRepo: Repository<ShiftTrackingDtl>,
  ) {}

  public async runDeleteShiftTrackingDtlProcedure(
    options?: ShiftTrackingDtlJobOptionsDto,
  ): Promise<void> {
    try {
      const parameters: Array<string | number> = [];
      const sqlParts: Array<string> = [];

      let parameterIndex = 0;

      if (options?.days !== undefined) {
        sqlParts.push(`@Days = @${parameterIndex}`);
        parameters.push(options.days);
        parameterIndex += 1;
      }

      if (options?.nbRowsToClean !== undefined) {
        sqlParts.push(`@NbRowsToClean = @${parameterIndex}`);
        parameters.push(options.nbRowsToClean);
        parameterIndex += 1;
      }

      if (options?.batchSize !== undefined) {
        sqlParts.push(`@BatchSize = @${parameterIndex}`);
        parameters.push(options.batchSize);
        parameterIndex += 1;
      }

      if (options?.delayMSBetweenRuns !== undefined) {
        sqlParts.push(`@DelayMSBetweenRuns = @${parameterIndex}`);
        parameters.push(options.delayMSBetweenRuns);
      }

      const sql = `EXEC dbo.usp_cleanup_shift_tracking_data ${sqlParts.join(', ')}`;

      await this.shiftTrackingDtlRepo.query(sql, parameters);
    } catch (error) {
      this.logger.error(
        `Failed to execute dbo.usp_cleanup_shift_tracking_data : ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }
}

