@ApiTags('Shift Tracking')
@Controller('shift-tracking')
@UseFilters(MesGenericErrorFilter)
export class ShiftTrackingController {
  public constructor(
    private readonly shiftTrackingService: ShiftTrackingService,
  ) {}

  @ApiOperation({
    summary:
      'Get hourly aggregated production, target, delta, status, and speed for a shift window.',
  })
  @ApiQuery({
    name: 'plant',
    type: String,
    required: true,
    description: 'Plant ID',
  })
  @ApiQuery({
    name: 'resourceId',
    type: String,
    required: true,
    description: 'Resource ID',
  })
  @ApiQuery({
    name: 'shiftStartDate',
    type: String,
    required: true,
    description: 'Shift start date (UTC, ISO string)',
  })
  @ApiQuery({
    name: 'shiftEndDate',
    type: String,
    required: true,
    description: 'Shift end date (UTC, ISO string)',
  })
  @ApiResponse({
    status: 200,
    description: 'Hourly aggregated production data',
    schema: {
      example: [
        {
          hour: '07:00',
          target: 100,
          production: 90,
          delta: -10,
          status: ';;;;;;;;;;;',
          speed: 'NA;NA;NA;NA;NA;NA;NA;NA;NA;NA;NA;NA',
          description:
            'Desc1;Desc2;Desc3;Desc4;Desc5;Desc6;Desc7;Desc8;Desc9;Desc10;Desc11;Desc12',
        },
      ],
    },
  })
  @ApiResponse({
    status: 404,
    description:
      'Hourly aggregated production not found for plant and resourceId.',
  })
  @ApiResponse({
    status: 500,
    description: 'Failed to retrieve hourly aggregated production.',
  })
  @Get('/hourly-aggregation')
  public async getHourlyAggregation(
    @Res() response: Response,
    @Query() query: HourlyAggregationQueryDto,
  ): Promise<Response> {
    const { plant, resourceId, shiftStartDate, shiftEndDate } = query;
    if (
      Number.isNaN(new Date(shiftStartDate).getTime()) ||
      Number.isNaN(new Date(shiftEndDate).getTime())
    ) {
      return response
        .status(HttpStatus.BAD_REQUEST)
        .json({ message: 'Invalid date format' });
    }
    // Convert date strings to Date objects in UTC
    const start = new Date(shiftStartDate);
    const end = new Date(shiftEndDate);
    const results =
      await this.shiftTrackingService.getHourlyAggregatedProduction(
        Number(plant),
        resourceId,
        start,
        end,
      );
    if (results && results.length > 0) {
      const responseObject = {
        plant: Number(query.plant),
        resourceId: query.resourceId,
        ...results,
      };
      return response.status(HttpStatus.OK).json(responseObject);
    }
    return response.status(HttpStatus.OK).json({
      message: `Hourly aggregated production not found for plant: ${plant}, and resource: ${resourceId}`,
    });
  }

  @ApiOperation({
    summary:
      'Get balancing drawer options (operators + targets) for a resource.',
    description:
      'Operators are read from assembly_line_config (config_type=OPERATOR). Targets are summed from cadence_config based on materials currently in production (change_tools with date_hour_to=9999-12-31).',
  })
  @ApiQuery({ name: 'plant', type: String, required: true })
  @ApiQuery({ name: 'resourceId', type: String, required: true })
  @ApiQuery({
    name: 'shiftCode',
    type: String,
    required: false,
    description: 'Shift code (1/2/3) used to pick operator config row.',
  })
  @Get('/balancing-options')
  public async getBalancingOptions(
    @Res() response: Response,
    @Query() query: BalancingOptionsQueryDto,
  ): Promise<Response> {
    const results = await this.shiftTrackingService.getBalancingOptions({
      plant: Number(query.plant),
      resourceId: query.resourceId,
      shiftCode:
        query.shiftCode === undefined ? undefined : Number(query.shiftCode),
    });
    return response.status(HttpStatus.OK).json(results);
  }

  @ApiOperation({
    summary:
      'Validate that a balancing configuration does not overlap an existing balancing range.',
  })
  @ApiQuery({ name: 'plant', type: String, required: true })
  @ApiQuery({ name: 'resourceId', type: String, required: true })
  @ApiQuery({ name: 'startDateTime', type: String, required: true })
  @ApiQuery({ name: 'endDateTime', type: String, required: true })
  @Get('/balancing-range')
  public async validateBalancingRange(
    @Res() response: Response,
    @Query() query: BalancingRangeQueryDto,
  ): Promise<Response> {
    const result = await this.shiftTrackingService.validateBalancingRange({
      plant: Number(query.plant),
      resourceId: query.resourceId,
      startDateTime: query.startDateTime,
      endDateTime: query.endDateTime,
      timezone: query.timezone,
    });

    return response.status(HttpStatus.OK).json(result);
  }

  @ApiOperation({
    summary:
      'Check whether a HOUR_ACTION already exists for a plant, resource, and hour window.',
  })
  @ApiQuery({ name: 'plant', type: String, required: true })
  @ApiQuery({ name: 'resourceId', type: String, required: true })
  @ApiQuery({ name: 'dateHourFrom', type: String, required: true })
  @ApiQuery({ name: 'dateHourTo', type: String, required: true })
  @Get('/hour-action-exists')
  public async hourActionExists(
    @Res() response: Response,
    @Query() query: HourActionExistsQueryDto,
  ): Promise<Response> {
    if (!query.dateHourFrom.trim() || !query.dateHourTo.trim()) {
      return response
        .status(HttpStatus.BAD_REQUEST)
        .json({ message: 'Invalid date format' });
    }

    const result = await this.shiftTrackingService.hourActionExists({
      plant: Number(query.plant),
      resourceId: query.resourceId,
      dateHourFrom: query.dateHourFrom,
      dateHourTo: query.dateHourTo,
    });

    return response.status(HttpStatus.OK).json(result);
  }

  @ApiOperation({
    summary:
      'Get reconstructed configuration timeline segments for Event Center in a shift window.',
  })
  @ApiQuery({ name: 'plant', type: String, required: true })
  @ApiQuery({ name: 'resourceId', type: String, required: true })
  @ApiQuery({ name: 'shiftStartDate', type: String, required: true })
  @ApiQuery({ name: 'shiftEndDate', type: String, required: true })
  @ApiResponse({
    status: 200,
    description:
      'Configuration timeline segments reconstructed by hour, including synthetic N gaps when the BA gap rule applies.',
    type: ConfigurationHistoryItemDto,
    isArray: true,
  })
  @Get('/configuration-history')
  public async getConfigurationHistory(
    @Res() response: Response,
    @Query() query: ConfigurationHistoryQueryDto,
  ): Promise<Response> {
    const { plant, resourceId, shiftStartDate, shiftEndDate } = query;
    if (
      Number.isNaN(new Date(shiftStartDate).getTime()) ||
      Number.isNaN(new Date(shiftEndDate).getTime())
    ) {
      return response
        .status(HttpStatus.BAD_REQUEST)
        .json({ message: 'Invalid date format' });
    }

    const results = await this.shiftTrackingService.getConfigurationHistory({
      plant: Number(plant),
      resourceId,
      shiftEndDate: new Date(shiftEndDate),
      shiftStartDate: new Date(shiftStartDate),
    });

    return response.status(HttpStatus.OK).json(results);
  }
}

