type ConfigActionDisplay = 'N' | 'N+' | 'N-' | 'SPECIAL';

interface ConfigTimelineSegment {
  action: ConfigActionDisplay;
  dateHourFrom: Date;
  dateHourTo: Date;
  sourceDateHourFrom: Date;
  sourceDateHourTo: Date;
}

/**
 * Maps persisted configuration actions to Event Center display labels.
 * @param action Persisted action value.
 * @returns Display label used by configuration history.
 */
function mapActionToDisplay(action: string): ConfigActionDisplay {
  const normalized = action.toUpperCase();
  if (normalized === 'LOW') {
    return 'N-';
  }
  if (normalized === 'HIGH') {
    return 'N+';
  }
  if (normalized === 'SPECIAL') {
    return 'SPECIAL';
  }
  return 'N';
}

/**
 * Serializes a SQL datetime value as UTC while preserving its wall-clock components.
 * This avoids server-timezone drift when DB datetime values are timezone-naive.
 * @param value SQL datetime represented as a JS Date.
 * @returns ISO string in UTC with trailing Z.
 */
function toUtcIsoPreservingClock(value: Date): string {
  const utcDate = new Date(
    Date.UTC(
      value.getFullYear(),
      value.getMonth(),
      value.getDate(),
      value.getHours(),
      value.getMinutes(),
      value.getSeconds(),
      value.getMilliseconds(),
    ),
  );
  return utcDate.toISOString();
}

/**
 * Formats a duration between two datetimes as HH:mm:ss.
 * @param from Start datetime.
 * @param to End datetime.
 * @returns Duration string.
 */
function formatCardDuration(from: Date, to: Date): string {
  const totalSeconds = Math.max(
    0,
    Math.floor((to.getTime() - from.getTime()) / 1000),
  );
  const hours = Math.floor(totalSeconds / 3600)
    .toString()
    .padStart(2, '0');
  const minutes = Math.floor((totalSeconds % 3600) / 60)
    .toString()
    .padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');

  return `${hours}:${minutes}:${seconds}`;
}

/**
 * Finds the latest configuration row ending before or exactly at a reference point.
 * @param rows Ordered configuration rows.
 * @param referencePoint End boundary used for backward reconstruction.
 * @returns The latest matching row, if any.
 */
function findLatestRowEndingBeforeOrAt(
  rows: Array<ActionsOnProduction>,
  referencePoint: Date,
): ActionsOnProduction | undefined {
  const referenceMs = referencePoint.getTime();

  for (let index = rows.length - 1; index >= 0; index -= 1) {
    const row = rows[index];
    if (row.dateHourTo.getTime() <= referenceMs) {
      return row;
    }
  }

  return undefined;
}

/**
 * Finds the effective configuration row at a reference point, or the latest row
 * ending before or exactly at that point when the hour ends in a gap.
 * @param rows Ordered configuration rows.
 * @param referencePoint Boundary used for backward reconstruction.
 * @returns The effective or latest prior row, if any.
 */
function findEffectiveRowAtOrBefore(
  rows: Array<ActionsOnProduction>,
  referencePoint: Date,
): ActionsOnProduction | undefined {
  const referenceMs = referencePoint.getTime();

  for (let index = rows.length - 1; index >= 0; index -= 1) {
    const row = rows[index];
    if (
      row.dateHourFrom.getTime() < referenceMs &&
      row.dateHourTo.getTime() >= referenceMs
    ) {
      return row;
    }
  }

  return findLatestRowEndingBeforeOrAt(rows, referencePoint);
}

/**
 * Finds the latest configuration row ending strictly before a reference point.
 * @param rows Ordered configuration rows.
 * @param referencePoint Boundary used for strict previous-row lookup.
 * @returns The latest matching row, if any.
 */
function findLatestRowEndingBefore(
  rows: Array<ActionsOnProduction>,
  referencePoint: Date,
): ActionsOnProduction | undefined {
  const referenceMs = referencePoint.getTime();

  for (let index = rows.length - 1; index >= 0; index -= 1) {
    const row = rows[index];
    if (row.dateHourTo.getTime() < referenceMs) {
      return row;
    }
  }

  return undefined;
}

/**
 * Reconstructs the effective configuration timeline for a selected hour.
 * @param rows Ordered configuration rows up to the shift end.
 * @param hourStart Start of the selected hour.
 * @param hourEnd End of the selected hour.
 * @returns Chronological timeline segments for the hour.
 */
function buildHourConfigurationSegments(
  rows: Array<ActionsOnProduction>,
  hourStart: Date,
  hourEnd: Date,
): Array<ConfigTimelineSegment> {
  const rowsOverlappingHour = rows.filter((row) => {
    return (
      row.dateHourFrom.getTime() < hourEnd.getTime() &&
      row.dateHourTo.getTime() > hourStart.getTime()
    );
  });

  if (rowsOverlappingHour.length === 0) {
    return [];
  }

  let referencePoint = new Date(hourEnd);
  const segmentsInReverse: Array<ConfigTimelineSegment> = [];
  let lastRowUsed: ActionsOnProduction | undefined;

  while (referencePoint.getTime() > hourStart.getTime()) {
    const candidate = findEffectiveRowAtOrBefore(rows, referencePoint);
    if (!candidate) {
      break;
    }

    lastRowUsed = candidate;

    const candidateTouchesHour =
      candidate.dateHourTo.getTime() > hourStart.getTime();

    const gapMs = referencePoint.getTime() - candidate.dateHourTo.getTime();
    if (candidateTouchesHour && gapMs > 60_000) {
      const gapStart = new Date(
        Math.max(candidate.dateHourTo.getTime(), hourStart.getTime()),
      );
      const gapEnd = new Date(referencePoint);

      if (gapEnd.getTime() > gapStart.getTime()) {
        segmentsInReverse.push({
          action: 'N',
          dateHourFrom: gapStart,
          dateHourTo: gapEnd,
          sourceDateHourFrom: gapStart,
          sourceDateHourTo: gapEnd,
        });
      }
    }

    const segmentStart = new Date(
      Math.max(candidate.dateHourFrom.getTime(), hourStart.getTime()),
    );
    const segmentEnd = new Date(
      Math.min(candidate.dateHourTo.getTime(), hourEnd.getTime()),
    );

    if (segmentEnd.getTime() > segmentStart.getTime()) {
      segmentsInReverse.push({
        action: mapActionToDisplay(candidate.action),
        dateHourFrom: segmentStart,
        dateHourTo: segmentEnd,
        sourceDateHourFrom: candidate.dateHourFrom,
        sourceDateHourTo: candidate.dateHourTo,
      });
    }

    if (candidate.dateHourFrom.getTime() <= hourStart.getTime()) {
      break;
    }

    referencePoint = new Date(candidate.dateHourFrom);
  }

  segmentsInReverse.reverse();
  const segments = segmentsInReverse;

  // Handle gap at end of hour: if the last segment doesn't reach hourEnd,
  // And the gap is > 1 minute, add synthetic N segment
  if (segments.length > 0) {
    const lastSegment = segments.at(-1);
    if (lastSegment) {
      const gapToHourEndMs =
        hourEnd.getTime() - lastSegment.dateHourTo.getTime();
      if (gapToHourEndMs > 60_000 && lastRowUsed) {
        const gapStart = new Date(lastSegment.dateHourTo);
        const segmentEnd = new Date(hourEnd.getTime() - 1000); // -1 second for 23:59:59
        segments.push({
          action: 'N',
          dateHourFrom: gapStart,
          dateHourTo: segmentEnd,
          sourceDateHourFrom: gapStart,
          sourceDateHourTo: segmentEnd,
        });
      }
    }
  }

  return segments;
}

/**
 * Converts reconstructed segments into API DTOs and computes their fromAction value.
 * @param segments Chronological timeline segments inside one hour.
 * @param rows Ordered configuration rows up to the shift end.
 * @param hourEnd The hour boundary (end of the current hour being processed).
 * @returns API DTOs for the hour timeline.
 */
function mapSegmentsToHistoryItems(
  segments: Array<ConfigTimelineSegment>,
  rows: Array<ActionsOnProduction>,
  hourEnd: Date,
): Array<ConfigurationHistoryItemDto> {
  return segments.map((segment, index) => {
    let fromAction: ConfigActionDisplay = 'N';

    if (index > 0) {
      fromAction = segments[index - 1].action;
    } else {
      const previousRow = findLatestRowEndingBefore(
        rows,
        segment.sourceDateHourFrom,
      );
      if (previousRow) {
        const diffMs =
          segment.sourceDateHourFrom.getTime() -
          previousRow.dateHourTo.getTime();
        if (diffMs <= 60_000) {
          fromAction = mapActionToDisplay(previousRow.action);
        }
      }
    }

    // Cap dateHourTo to HH:59:59 of the current hour
    const cappedDateHourTo =
      segment.dateHourTo.getTime() >= hourEnd.getTime()
        ? new Date(hourEnd.getTime() - 1000)
        : segment.dateHourTo;

    return {
      action: segment.action,
      dateHourFrom: toUtcIsoPreservingClock(segment.dateHourFrom),
      dateHourTo: toUtcIsoPreservingClock(cappedDateHourTo),
      duration:
        segment.action === 'N'
          ? ''
          : formatCardDuration(segment.dateHourFrom, cappedDateHourTo),
      fromAction,
    };
  });
}

/**
 * Prefer the local tool wording from ROUTING_PRT, otherwise fall back to the
 * current tool id without its leading zero padding.
 * @param localTool The local tool wording from ROUTING_PRT, if available.
 * @param toolId The tool id to use if localTool is not provided. Leading zeroes will be removed.
 * @returns The display string for the tool, or null if neither value is available.
 */
function resolveDisplayedTool(
  localTool?: string | null,
  toolId?: string | null,
): string | null {
  const localToolValue = localTool?.trim();
  if (localToolValue) {
    return localToolValue;
  }

  const toolValue = toolId?.trim();
  if (!toolValue) {
    return null;
  }

  return toolValue;
}

/**
 * Formats a Luxon DateTime object to a SQL datetime string (yyyy-MM-dd HH:mm:ss.SSS).
 * @param dateTime The Luxon DateTime object to format.
 * @returns The formatted SQL datetime string.
 */
function formatSqlDateTime(dateTime: DateTime): string {
  return dateTime.toFormat('yyyy-MM-dd HH:mm:ss.SSS');
}

/**
 *
 * @param queryBuilder The query builder instance to use for constructing the subquery.
 * @param alias The alias of the main query's table (e.g., 'ct') to reference in the subquery's where clause.
 * @param plant The plant number to filter the records.
 * @param resourceId The resource ID to filter the records.
 * @returns A string representing the SQL condition to filter records with the latest active dateHourFrom for the given plant and resourceId.
 *
 * This function constructs a SQL condition that ensures only the record(s) with the maximum dateHourFrom (i.e., the latest active record) for a specific plant and resourceId are selected. It does this by creating a subquery that retrieves the maximum dateHourFrom from the ChangeTools table for the given plant and resourceId, where dateHourTo is '9999-12-31' (indicating active records). The main query can then use this condition to filter results accordingly.
 */
function buildLatestActiveDateFromFilter(
  queryBuilder: SelectQueryBuilder<ChangeTools>,
  alias: string,
  plant: number,
  resourceId: string,
): string {
  const latestDateFromSubQuery = queryBuilder
    .subQuery()
    .select('MAX(ct2.dateHourFrom)')
    .from(ChangeTools, 'ct2')
    .where('ct2.plant = :plant', { plant })
    .andWhere('ct2.resourceId = :resourceId', { resourceId })
    .andWhere('CAST(ct2.dateHourTo AS DATE) = :maxDate', {
      maxDate: '9999-12-31',
    })
    .getQuery();

  return `${alias}.dateHourFrom = ${latestDateFromSubQuery}`;
}

@Injectable()
export class ShiftTrackingService {
  private readonly logger = new Logger(ShiftTrackingService.name);

  public constructor(
    @InjectRepository(ShiftTrackingStatus)
    private readonly shiftTrackingRepository: Repository<ShiftTrackingStatus>,
    @InjectRepository(ChangeTools)
    private readonly changeToolsRepository: Repository<ChangeTools>,
    @InjectRepository(AssemblyLineConfig)
    private readonly assemblyLineConfigRepository: Repository<AssemblyLineConfig>,
    @InjectRepository(CadenceConfig)
    private readonly cadenceConfigRepository: Repository<CadenceConfig>,
    @InjectRepository(ActionsOnProduction)
    private readonly actionsOnProductionRepository: Repository<ActionsOnProduction>,
    @InjectRepository(ShiftTrackingDtl)
    private readonly shiftTrackingDetailsRepository: Repository<ShiftTrackingDtl>,
  ) {}

  private async getMaterialsInProduction(
    plant: number,
    resourceId: string,
  ): Promise<Array<string>> {
    const toolMaterialRows = await this.changeToolsRepository
      .createQueryBuilder('ct')
      .select(['ct.materialId'])
      .where('ct.plant = :plant', { plant })
      .andWhere('ct.resourceId = :resourceId', { resourceId })
      .andWhere('CAST(ct.dateHourTo AS DATE) = :maxDate', {
        maxDate: '9999-12-31',
      })
      .andWhere((queryBuilder) =>
        buildLatestActiveDateFromFilter(queryBuilder, 'ct', plant, resourceId),
      )
      .getMany();

    return [
      ...new Set(toolMaterialRows.map((row) => row.materialId).filter(Boolean)),
    ].sort((left, right) => String(left).localeCompare(String(right)));
  }

  private async getBalancingTargets(
    plant: number,
    resourceId: string,
    materialsInProduction: Array<string>,
  ): Promise<BalancingTargets> {
    if (materialsInProduction.length === 0) {
      return { high: 0, low: 0, matchedRows: 0, normal: 0 };
    }

    const rows = await this.cadenceConfigRepository
      .createQueryBuilder('cc')
      .where('cc.plant = :plant', { plant })
      .andWhere('cc.resourceId = :resourceId', { resourceId })
      .andWhere('cc.materialId IN (:...materials)', {
        materials: materialsInProduction,
      })
      .getMany();

    const totals = { high: 0, low: 0, matchedRows: rows.length, normal: 0 };

    for (const row of rows) {
      totals.low += Number(row.cadenceLow ?? 0);
      totals.normal += Number(row.cadenceNormal ?? 0);
      totals.high += Number(row.cadenceHigh ?? 0);
    }

    return totals;
  }

  public async validateBalancingRange(parameters: {
    plant: number;
    resourceId: string;
    startDateTime: string;
    endDateTime: string;
    timezone?: string;
  }): Promise<{
    valid: boolean;
    hasConflict: boolean;
    message?: string;
    shiftCode: number | null;
    shiftStartDateTime: Date | null;
    shiftEndDateTime: Date | null;
  }> {
    const start = DateTime.fromFormat(
      parameters.startDateTime,
      'MM/dd/yyyy HH:mm:ss',
      { zone: parameters.timezone ?? 'utc' },
    );
    const end = DateTime.fromFormat(
      parameters.endDateTime,
      'MM/dd/yyyy HH:mm:ss',
      { zone: parameters.timezone ?? 'utc' },
    );

    if (!start.isValid || !end.isValid) {
      return {
        valid: false,
        hasConflict: false,
        message: 'Invalid balancing date-time format.',
        shiftCode: null,
        shiftEndDateTime: null,
        shiftStartDateTime: null,
      };
    }

    if (end <= start) {
      return {
        valid: false,
        hasConflict: false,
        message: 'End time must be after start time.',
        shiftCode: null,
        shiftEndDateTime: null,
        shiftStartDateTime: null,
      };
    }

    const localStartSql = formatSqlDateTime(start);
    const localEndSql = formatSqlDateTime(end);
    const utcStartSql = formatSqlDateTime(start.toUTC());
    const utcEndSql = formatSqlDateTime(end.toUTC());

    const createConflictQuery = (
      startSql: string,
      endSql: string,
    ): SelectQueryBuilder<ActionsOnProduction> => {
      return this.actionsOnProductionRepository
        .createQueryBuilder('aop')
        .where('aop.plant = :plant', { plant: parameters.plant })
        .andWhere('aop.resourceId = :resourceId', {
          resourceId: parameters.resourceId,
        })
        .andWhere('UPPER(aop.action) <> :hourAction', {
          hourAction: 'HOUR_ACTION',
        })
        .andWhere('aop.dateHourFrom < :end', { end: endSql })
        .andWhere('aop.dateHourTo > :start', { start: startSql });
    };

    const [localConflictCount, utcConflictCount] = await Promise.all([
      createConflictQuery(localStartSql, localEndSql).getCount(),
      createConflictQuery(utcStartSql, utcEndSql).getCount(),
    ]);

    if (localConflictCount > 0 || utcConflictCount > 0) {
      return {
        valid: false,
        hasConflict: true,
        message:
          'Selected balancing range conflicts with an existing balancing configuration.',
        shiftCode: null,
        shiftEndDateTime: null,
        shiftStartDateTime: null,
      };
    }

    return {
      valid: true,
      hasConflict: false,
      shiftCode: null,
      shiftEndDateTime: null,
      shiftStartDateTime: null,
    };
  }

  public async getHourlyAggregatedProduction(
    plant: number,
    resourceId: string,
    shiftStartDate: Date,
    shiftEndDate: Date,
  ): Promise<Array<HourlyAggregatedProductionDto>> {
    try {
      /* ============================================================
       1️⃣ QUERY 1 — Hourly aggregation
       ============================================================ */
      const hourlyRowsPromise = this.shiftTrackingRepository
        .createQueryBuilder('st')
        .innerJoin(
          ShiftTrackingDtl, // When entity is used, then we must use entity properties and not DB column names in below clauses
          'dtl',
          `
            dtl.plant = st.plant
            AND dtl.resource_id = st.resource_id
            AND dtl.date_hour_from = st.date_hour_from
          `,
        )
        .where('dtl.plant = :plant', { plant })
        .andWhere('dtl.resourceId = :resourceId', { resourceId })
        .andWhere('dtl.dateHourFrom >= :shiftStartDate', { shiftStartDate }) // To make use of existing non-clustered index on plant,resourceId,dateHourFrom
        .andWhere('dtl.dateHourFrom <= :shiftEndDate', { shiftEndDate }) // To make use of existing non-clustered index on plant,resourceId,dateHourFrom
        .andWhere('dtl.dateShiftStart = :shiftStartDate', { shiftStartDate })
        .andWhere('dtl.dateShiftEnd = :shiftEndDate', { shiftEndDate })
        .select([
          // Hour formatted with leading zero
          "RIGHT('0' + CAST(DATEPART(HOUR, st.dateHourFrom) AS VARCHAR(2)), 2) AS hour",

          // Datetime boundaries
          'st.dateHourFrom AS dateHourFrom',
          'MIN(st.dateHourTo) AS dateHourTo',

          // Hourly details
          'MIN(st.status) AS status',
          'MIN(st.speed) AS speed',
          'MIN(dtl.slowdown) AS slowdown',

          // Aggregated metrics
          'SUM(dtl.targetQty) AS target',
          'SUM(dtl.realQty) AS production',
        ])
        .groupBy('st.dateHourFrom')
        .orderBy('st.dateHourFrom', 'ASC')
        .getRawMany();

      /* ============================================================
       2️⃣ QUERY 2 — Tools & materials (executed ONCE)
       ============================================================ */
      const toolMaterialRowsPromise = this.changeToolsRepository
        .createQueryBuilder('ct')
        .leftJoin(
          RoutingPrt,
          'rp',
          'rp.plant = ct.plant AND rp.toolId = ct.toolId',
        )
        .select([
          'ct.tool_id AS toolId',
          'ct.material_id AS materialId',
          'rp.local_tool AS localTool',
        ])
        .where('ct.plant = :plant', { plant })
        .andWhere('ct.resourceId = :resourceId', { resourceId })
        .andWhere('CAST(ct.dateHourTo AS DATE) = :maxDate', {
          maxDate: '9999-12-31',
        })
        // This condition ensures we only get the currently active tool/material for the resource, even if there are multiple records with dateHourTo = '9999-12-31' due to future-dated changes. By comparing dateHourFrom to the latest one, we ensure we get the most recent active record.
        .andWhere((queryBuilder) =>
          buildLatestActiveDateFromFilter(
            queryBuilder,
            'ct',
            plant,
            resourceId,
          ),
        )
        .getRawMany<ToolMaterialRow>();

      const actionsRowsPromise = this.actionsOnProductionRepository
        .createQueryBuilder('aop')
        .where('aop.plant = :plant', { plant })
        .andWhere('aop.resourceId = :resourceId', { resourceId })
        .andWhere('aop.dateHourFrom >= :shiftStartDate', { shiftStartDate })
        .andWhere('aop.dateHourTo <= :shiftEndDate', { shiftEndDate })
        .getMany();

      // Run independent queries in parallel
      const [hourlyRows, toolMaterialRows, actionsRows] = await Promise.all([
        hourlyRowsPromise,
        toolMaterialRowsPromise,
        actionsRowsPromise,
      ]);
      if (hourlyRows.length === 0) {
        return [];
      }

      /* ============================================================
       3️⃣ Remove duplicates and join
       ============================================================ */
      const uniqueTools = [
        ...new Set(
          toolMaterialRows
            .map((row) => resolveDisplayedTool(row.localTool, row.toolId))
            .filter(Boolean),
        ),
      ];
      const uniqueMaterials = [
        ...new Set(
          toolMaterialRows.map((row) => row.materialId).filter(Boolean),
        ),
      ];

      const toolUnique = uniqueTools.length > 0 ? uniqueTools.join(';') : null;
      const materialUnique =
        uniqueMaterials.length > 0 ? uniqueMaterials.join(';') : null;

      return hourlyRows.map((r) => {
        const target = Number(r.target) || 0;
        const production = Number(r.production) || 0;

        const deltaRaw = target - production;
        const delta =
          target > production ? -Math.abs(deltaRaw) : Math.abs(deltaRaw);

        // Find actions-on-production descriptions for this hour
        const hourActions = actionsRows.filter((aop) => {
          return (
            aop.dateHourFrom.getTime() === new Date(r.dateHourFrom).getTime() &&
            aop.dateHourTo.getTime() === new Date(r.dateHourTo).getTime()
          );
        });
        const description = hourActions
          .map((aop) => aop.description)
          .filter(Boolean)
          .join(' | ');

        return {
          hour: r.hour,
          dateHourFrom: r.dateHourFrom,
          dateHourTo: r.dateHourTo,

          status: r.status,
          speed: r.speed,
          slowdown: r.slowdown,

          target,
          production,
          delta,

          material: materialUnique,
          tool: toolUnique,
          description,
        } as HourlyAggregatedProductionDto;
      });
    } catch (error) {
      this.logger.error(
        `Error in getHourlyAggregatedProduction: ${error.message}`,
        error.stack,
      );
      return [];
    }
  }

  public async getBalancingOptions(parameters: {
    plant: number;
    resourceId: string;
    shiftCode?: number;
  }): Promise<{
    plant: number;
    resourceId: string;
    shiftCode?: number;
    operators: {
      low: number | null;
      normal: number | null;
      high: number | null;
    };
    targets: {
      low: number;
      normal: number;
      high: number;
      materialsInProduction: Array<string>;
    };
  }> {
    const { plant, resourceId, shiftCode } = parameters;

    const operators = await (async (): Promise<{
      low: number | null;
      normal: number | null;
      high: number | null;
    }> => {
      try {
        const query = this.assemblyLineConfigRepository
          .createQueryBuilder('alc')
          .where('alc.plant = :plant', { plant })
          .andWhere('alc.resourceId = :resourceId', { resourceId })
          .andWhere('UPPER(alc.configType) = :configType', {
            configType: 'OPERATORS',
          });

        if (shiftCode !== undefined) {
          query.andWhere('alc.shiftCode = :shiftCode', { shiftCode });
        }

        const row = await query.orderBy('alc.updatedAt', 'DESC').getOne();

        return {
          high: row?.nbHigh ?? null,
          low: row?.nbLow ?? null,
          normal: row?.nbMedium ?? null,
        };
      } catch (error) {
        this.logger.error(
          `Error reading assembly_line_config for balancing options: ${error.message}`,
          error.stack,
        );
        return { high: null, low: null, normal: null };
      }
    })();

    const materialsInProduction = await this.getMaterialsInProduction(
      plant,
      resourceId,
    );
    const targets = await this.getBalancingTargets(
      plant,
      resourceId,
      materialsInProduction,
    );

    return {
      plant,
      resourceId,
      shiftCode,
      operators,
      targets: {
        ...targets,
        materialsInProduction,
      },
    };
  }

  public async hourActionExists(parameters: {
    plant: number;
    resourceId: string;
    dateHourFrom: string;
    dateHourTo: string;
  }): Promise<{ exists: boolean }> {
    const count = await this.actionsOnProductionRepository
      .createQueryBuilder('aop')
      .where('aop.plant = :plant', { plant: parameters.plant })
      .andWhere('aop.resourceId = :resourceId', {
        resourceId: parameters.resourceId,
      })
      .andWhere('aop.dateHourFrom = :dateHourFrom', {
        dateHourFrom: parameters.dateHourFrom,
      })
      .andWhere('aop.dateHourTo = :dateHourTo', {
        dateHourTo: parameters.dateHourTo,
      })
      .andWhere('UPPER(aop.action) = :action', { action: 'HOUR_ACTION' })
      .getCount();
    return { exists: count > 0 };
  }

  public async getConfigurationHistory(parameters: {
    plant: number;
    resourceId: string;
    shiftStartDate: Date;
    shiftEndDate: Date;
  }): Promise<Array<ConfigurationHistoryItemDto>> {
    const allowedActions = ['LOW', 'NORMAL', 'HIGH', 'SPECIAL'];
    const shiftStartHour = DateTime.fromJSDate(parameters.shiftStartDate, {
      zone: 'utc',
    }).startOf('hour');
    const shiftEndHour = DateTime.fromJSDate(parameters.shiftEndDate, {
      zone: 'utc',
    }).startOf('hour');

    if (!shiftStartHour.isValid || !shiftEndHour.isValid) {
      return [];
    }

    const allRowsUntilShiftEnd = await this.actionsOnProductionRepository
      .createQueryBuilder('aop')
      .where('aop.plant = :plant', { plant: parameters.plant })
      .andWhere('aop.resourceId = :resourceId', {
        resourceId: parameters.resourceId,
      })
      .andWhere('UPPER(aop.action) IN (:...actions)', {
        actions: allowedActions,
      })
      .andWhere('aop.dateHourTo <= :shiftEndDate', {
        shiftEndDate: parameters.shiftEndDate,
      })
      .orderBy('aop.dateHourTo', 'ASC')
      .addOrderBy('aop.dateHourFrom', 'ASC')
      .addOrderBy('aop.id', 'ASC')
      .getMany();

    const historyItems: Array<ConfigurationHistoryItemDto> = [];
    let hourCursor = shiftStartHour;

    while (hourCursor <= shiftEndHour) {
      const hourStart = hourCursor.toJSDate();
      const hourEnd = hourCursor.plus({ hours: 1 }).toJSDate();
      const hourSegments = buildHourConfigurationSegments(
        allRowsUntilShiftEnd,
        hourStart,
        hourEnd,
      );

      historyItems.push(
        ...mapSegmentsToHistoryItems(
          hourSegments,
          allRowsUntilShiftEnd,
          hourEnd,
        ),
      );
      hourCursor = hourCursor.plus({ hours: 1 });
    }

    return historyItems;
  }
}

import { DateTime } from 'luxon';

/**
 * Parses a shift tracking date-time string in 'MM/dd/yyyy HH:mm:ss' format (UTC).
 * @param value The date-time string to parse, formatted as 'MM/dd/yyyy HH:mm:ss'.
 * @returns The parsed Date object in UTC.
 */
export function parseShiftTrackingDateTime(value: string): Date {
  const formatted = DateTime.fromFormat(value, 'MM/dd/yyyy HH:mm:ss', {
    zone: 'utc',
  });
  if (formatted.isValid) {
    return formatted.toJSDate();
  }

  const iso = DateTime.fromISO(value, { zone: 'utc' });
  if (iso.isValid) {
    return iso.toJSDate();
  }

  throw new Error(`Invalid datetime value: ${value}`);
}

