import { ValueTransformer } from 'typeorm';

const nullSentinel: unknown = JSON.parse('null');

export const asNumberOrUndefined = (value: unknown): number | undefined => {
  if (value === undefined || value === '' || Object.is(value, nullSentinel)) {
    return undefined;
  }
  const numericValue = Number(value);
  return Number.isFinite(numericValue) ? numericValue : undefined;
};

export const numericToNumber: ValueTransformer = {
  to: asNumberOrUndefined,
  from: asNumberOrUndefined,
};

